/**
 * One Git provider behind Release Relay: GitHub, GitLab, Bitbucket or Azure DevOps.
 * Each connection names its provider and the Named Credential that holds the token.
 * The token only needs to read the repository and start the Release Relay pipeline:
 * pushing, opening, merging and deploying happen in the pipeline.
 */
public abstract with sharing class RlyGitProvider {

    public class GitException extends Exception {}

    private static final Integer TIMEOUT_MS = 20000;

    public class Entry {
        @AuraEnabled public String name;
        @AuraEnabled public String kind; // dir or file
        public String sha;               // blob or tree hash, when the provider gives it
    }

    public class Run {
        public String id;
        public String status;     // queued, in_progress, completed
        public String conclusion; // success, failure, cancelled
        public String url;
        public Datetime createdAt;

        /** True when the run started after the given time (two minutes' leeway for clock differences). */
        public Boolean startedAfter(Datetime t) {
            return t == null || (createdAt != null && createdAt >= t.addMinutes(-2));
        }
    }

    /** What starting the pipeline returned: a run id and link when the provider gives them. */
    public class Started {
        public String runId;
        public String url;
    }

    public class PullRequest {
        public Integer num;
        public String url;
        public String state;      // open, closed
        public Boolean merged;
    }

    public class PrFile {
        @AuraEnabled public String filename;
        @AuraEnabled public String status;     // added, modified, removed, renamed
        @AuraEnabled public Integer additions;
        @AuraEnabled public Integer deletions;
        @AuraEnabled public String patch;      // unified diff; empty when the provider gives none
        @AuraEnabled public Boolean truncated;
        @AuraEnabled public String baseRef;    // for providers without patches: versions to compare
        @AuraEnabled public String headRef;
    }

    public class Comparison {
        @AuraEnabled public Integer aheadBy;
        @AuraEnabled public Integer behindBy;
        @AuraEnabled public String url;
        @AuraEnabled public List<String> files = new List<String>();
    }

    protected RlySettings.Connection conn;
    protected String base;

    /** The adapter for a connection's provider. */
    public static RlyGitProvider forConnection(RlySettings.Connection c) {
        RlyGitProvider p;
        if (c.connectionType == RlySettings.GITLAB) {
            p = new RlyGitLabService();
        } else if (c.connectionType == RlySettings.BITBUCKET) {
            p = new RlyBitbucketService();
        } else if (c.connectionType == RlySettings.AZURE) {
            p = new RlyAzureDevOpsService();
        } else if (c.connectionType == RlySettings.GITHUB) {
            p = new RlyGitHubService();
        } else {
            throw new GitException('Connection ' + c.label + ' is ' + c.connectionType + ', not a Git connection.');
        }
        p.init(c);
        return p;
    }

    protected virtual void init(RlySettings.Connection c) {
        if (String.isBlank(c.repository) || c.repository.startsWith('REPLACE') || !repositoryPattern().matcher(c.repository.trim()).matches()) {
            throw new GitException('Set Repository on connection ' + c.label + ' as ' + repositoryHint() + '.');
        }
        this.conn = c;
        this.base = 'callout:' + c.namedCredential;
    }

    // ---------- what each provider implements ----------

    public abstract Pattern repositoryPattern();
    public abstract String repositoryHint();
    public abstract Boolean branchExists(String branch);
    public abstract List<String> listBranches();
    /** Raw file at a ref, or null when the file isn't there. */
    public abstract String getFileRaw(String filePath, String ref);
    /** Entries of one folder; empty when the folder doesn't exist. */
    public abstract List<Entry> listDir(String folderPath, String ref);
    public abstract Comparison compare(String base, String head);
    /** Starts the Release Relay pipeline with these inputs. */
    public abstract Started startPipeline(Map<String, String> inputs);
    /** The run for this release: by its stored id when the provider gave one, else the newest matching run. */
    public abstract Run findRun(String releaseName, String runMode, String knownRunId);
    public abstract PullRequest findPullRequest(String branch, String target);
    public abstract List<PrFile> pullFiles(Integer prNumber, String target, String branch);

    /** True when files can be edited from Salesforce (saveFile and createBranch are implemented). */
    /**
     * Every file path in a branch with its blob hash, in one call, or null when the provider
     * doesn't offer it (callers then fall back to folder listings).
     */
    public virtual Map<String, String> treeShas(String ref) {
        return null;
    }

    public virtual Boolean canWrite() {
        return false;
    }

    /** Writes one file to a branch as a new commit. Needs a token that can write repository contents. */
    public virtual void saveFile(String filePath, String branch, String content, String message) {
        throw new GitException('Editing files from Salesforce isn\'t available for ' + conn.connectionType + ' yet. Edit the branch in ' + conn.connectionType + '.');
    }

    /** Creates a branch at another branch's latest commit. */
    public virtual void createBranch(String branch, String fromRef) {
        throw new GitException('Creating branches from Salesforce isn\'t available for ' + conn.connectionType + ' yet.');
    }

    /** "pull request" or "merge request", for messages. */
    public virtual String changeLabel() {
        return 'pull request';
    }

    // ---------- shared HTTP helpers ----------

    protected HttpResponse send(String method, String path, String body, Map<String, String> headers) {
        HttpRequest req = new HttpRequest();
        req.setMethod(method);
        req.setEndpoint(path.startsWith('callout:') ? path : base + path);
        req.setTimeout(TIMEOUT_MS);
        req.setHeader('User-Agent', 'Release-Relay-Salesforce');
        if (headers != null) {
            for (String h : headers.keySet()) {
                req.setHeader(h, headers.get(h));
            }
        }
        if (body != null) {
            req.setHeader('Content-Type', 'application/json');
            req.setBody(body);
        }
        return new Http().send(req);
    }

    protected void assertOk(HttpResponse res, String action) {
        Integer code = res.getStatusCode();
        if (code < 200 || code >= 300) {
            String advice = code == 401 ? ' Check the token in the ' + conn.namedCredential + ' Named Credential.'
                : code == 403 ? ' The token lacks permission for this, or the provider rate-limited the request.'
                : code == 404 ? ' Check the repository and that the token can see it.'
                : (code == 400 || code == 422) ? ' The provider rejected the request; for a pipeline start, check the pipeline name and branch.'
                : '';
            throw new GitException(action + ' failed with HTTP ' + code + '.' + advice + ' ' + String.valueOf(res.getBody()).left(300));
        }
    }

    public static Object parse(HttpResponse res) {
        return JSON.deserializeUntyped(res.getBody());
    }

    public static Integer toInt(Object o) {
        try {
            return o == null ? 0 : Integer.valueOf(String.valueOf(o));
        } catch (Exception e) {
            return 0;
        }
    }

    public static Datetime parseTime(Object value) {
        if (value == null) {
            return null;
        }
        try {
            return (Datetime) JSON.deserialize('"' + String.valueOf(value) + '"', Datetime.class);
        } catch (Exception e) {
            return null;
        }
    }

    public static String enc(String value) {
        return EncodingUtil.urlEncode(value == null ? '' : value, 'UTF-8').replace('+', '%20');
    }

    /** Encodes each path segment but keeps the slashes. */
    public static String encPath(String path) {
        List<String> parts = new List<String>();
        for (String p : (path == null ? '' : path).split('/')) {
            parts.add(enc(p));
        }
        return String.join(parts, '/');
    }

    public static Entry entry(String name, Boolean isDir) {
        Entry e = new Entry();
        e.name = name;
        e.kind = isDir ? 'dir' : 'file';
        return e;
    }

    /** Counts added and removed lines in a unified diff. */
    public static void countLines(PrFile f) {
        f.additions = 0;
        f.deletions = 0;
        for (String line : (f.patch == null ? '' : f.patch).split('\n')) {
            if (line.startsWith('+') && !line.startsWith('+++')) {
                f.additions++;
            } else if (line.startsWith('-') && !line.startsWith('---')) {
                f.deletions++;
            }
        }
    }

    /** Keeps total patch text inside the heap budget. Returns the budget left. */
    public static Integer fitPatch(PrFile f, String patch, Integer budget) {
        String p = patch == null ? '' : patch;
        Integer room = Math.max(0, Math.min(60000, budget));
        f.truncated = p.length() > room;
        f.patch = p.left(room);
        return budget - f.patch.length();
    }
}
